// From: HG_SDF (License: MIT)
// https://mercury.sexy/
// Repeat around the origin by a fixed angle.
// For easier use, num of repetitions is use to specify the angle.
float opSmoothPolarRepeat(inout vec3 p, in float repetitions, in float offsetX, in float offsetAngle, in float smoothness)
{
    vec2 p2 = p.xz;

    float angle = 2.0*PI/repetitions;
    float a = atan(p2.y, p2.x) + angle/2. + offsetAngle;
    float r = length(p2);
    float c = floor(a/angle);
    a = modEx(a,angle, smoothness) - angle/2.;
    p2 = vec2(cos(a), sin(a))*r;
    // For an odd number of repetitions, fix cell index of the cell in -x direction
    // (cell index would be e.g. -5 and 5 in the two halves of the cell):
    if (abs(c) >= (repetitions/2.0)) 
        c = abs(c);

    p.xz = p2;

    p.x -= offsetX;

    return c;
}
